package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.net.Uri;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.json.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class Backup513Test {
    WorkTestSupport w;@Before public void setup()throws Exception{w=new WorkTestSupport();}@After public void close(){w.close();}
    File backup(boolean conversations,boolean wav)throws Exception{File zip=new File(w.app.getCacheDir(),"full-"+UUID.randomUUID()+".zip");try(OutputStream out=new FileOutputStream(zip)){WorkspaceBackup.write(w.app,out,false,()->false,s->{},new BackupExtras.Options(conversations,wav));}return zip;}
    @Test public void optionalConversationSurvivesRestoreWithAnOpenableSourceAndNoCredentialExport()throws Exception{long book=w.book("Livro.txt","Texto de origem.");SeekyAiStore store=new SeekyAiStore(w.app);SeekyAiStore.Session session=store.create("Livro","Texto de origem.","Parte 1",StudyFileProvider.uri(w.app,book).toString(),"text/plain","Livro.txt",0,book,0);session.append("Resume.",new SeekyAiCore.Result("Uma resposta com fonte [T1].",false));store.save(session);w.app.getSharedPreferences("seeky_ai_vault",0).edit().putString("keys","private-vault-fixture").apply();File zip=backup(true,false);store.delete(session.id());try(WorkspaceBackup.Staged staged=WorkspaceBackup.stage(w.app,zip,false,()->false,s->{})){WorkspaceBackup.restore(w.app,staged,()->false,s->{});}SeekyAiStore.Session restored=new SeekyAiStore(w.app).load(session.id());assertEquals(2,restored.messages.size());assertEquals(StudyFileProvider.uri(w.app,book).toString(),restored.s("uri"));assertEquals(TaskStore.workspace(w.app),restored.s("workspace_id"));assertEquals(1,new SeekyAiStore(w.app).list().size());assertEquals("private-vault-fixture",w.app.getSharedPreferences("seeky_ai_vault",0).getString("keys",""));try(ZipFile archive=new ZipFile(zip)){String manifest=new String(archive.getInputStream(archive.getEntry("workspace.json")).readAllBytes(),"UTF-8");assertFalse(manifest.contains("private-vault-fixture"));}}
    @Test public void optionalExternalWavRestoresItsBytesAndTrackIndex()throws Exception{long book=w.book("Livro.txt","Texto.");File audio=new File(w.app.getCacheDir(),"external-output.wav");VoiceToolsTest.writeWav(audio,new byte[]{1,0,2,0,3,0});NarrationIndex.register(w.app,Uri.fromFile(audio),StudyFileProvider.uri(w.app,book).toString(),"Capítulo 1",1,Collections.singletonList(new WavCues.Cue(0,"Introdução",0)));byte[] original=Files.readAllBytes(audio.toPath());File zip=backup(false,true);audio.delete();try(WorkspaceBackup.Staged staged=WorkspaceBackup.stage(w.app,zip,false,()->false,s->{})){WorkspaceBackup.restore(w.app,staged,()->false,s->{});}try(PlusStore db=new PlusStore(w.app)){StudyStore.Row track=db.rows("audio_tracks",null,null,null,1).get(0);Uri restored=Uri.parse(track.s("uri"));assertEquals("file",restored.getScheme());File file=new File(restored.getPath());assertTrue(file.getPath().contains("/narrations/"));assertArrayEquals(original,Files.readAllBytes(file.toPath()));assertEquals("Introdução",NarrationIndex.load(w.app,restored).get(0).label);}}
    @Test public void allPerBookBackgroundsAreIncludedEvenWhenAnotherIsGloballySelected()throws Exception{long book=w.book("Livro.txt","Texto.");String hash=w.book(book).s("hash");File root=new File(w.app.getFilesDir(),"backgrounds");root.mkdirs();File first=new File(root,"first.audio"),second=new File(root,"second.audio");Files.write(first.toPath(),new byte[]{1,2});Files.write(second.toPath(),new byte[]{3,4});BookSettings.update(w.app,hash,v->v.put("profile",new JSONObject().put("background_path",first.getPath()).put("background_volume",17)));w.app.getSharedPreferences("reading_background",0).edit().putString("path",second.getPath()).apply();File zip=backup(false,false);try(WorkspaceBackup.Staged staged=WorkspaceBackup.stage(w.app,zip,false,()->false,s->{})){WorkspaceBackup.restore(w.app,staged,()->false,s->{});}JSONObject profile=BookSettings.get(w.app,hash).getJSONObject("profile");assertFalse(first.getPath().equals(profile.getString("background_path")));assertArrayEquals(new byte[]{1,2},Files.readAllBytes(new File(profile.getString("background_path")).toPath()));assertEquals(17,profile.getInt("background_volume"));}
    @Test public void failedApplyReturnsMovedBooksToTheVerifiedStageForRetry()throws Exception{long book=w.book("Livro.txt","Texto original.");File zip=backup(false,false);try(WorkspaceBackup.Staged staged=WorkspaceBackup.stage(w.app,zip,false,()->false,s->{})){Map<String,byte[]> payload=new HashMap<>();for(Map.Entry<String,File> e:staged.entries.entrySet())if(e.getKey().startsWith("payload/"))payload.put(e.getKey(),Files.readAllBytes(e.getValue().toPath()));try{WorkspaceBackup.restore(w.app,staged,()->false,message->{if(message.equals("A recuperar biblioteca, cadernos e preferências…"))throw new IllegalStateException("Fixture interruption before transaction");});fail();}catch(IllegalStateException expected){}for(Map.Entry<String,byte[]> e:payload.entrySet())assertArrayEquals(e.getValue(),Files.readAllBytes(staged.entries.get(e.getKey()).toPath()));assertTrue(new File(w.book(book).s("path")).isFile());assertFalse(WorkspaceBackup.pending(w.app).exists());WorkspaceBackup.restore(w.app,staged,()->false,s->{});assertEquals("Livro.txt",w.book(book).s("title"));}}
    @Test public void startupRollbackReversesAJournalledMoveBeforeDeletingNewFiles()throws Exception{File stage=new File(w.app.getCacheDir(),"workspace-restore-fixture");stage.mkdirs();File source=new File(stage,"part-0"),dir=StudyFileProvider.directory(w.app),target=new File(dir,"restore-fixture.txt");Files.write(source.toPath(),new byte[]{4,5,6});Map<String,String> moves=new LinkedHashMap<>();moves.put(source.getPath(),target.getPath());WorkspaceBackup.preparePending(w.app,"not-committed",WorkspaceBackup.preferences(w.app),Collections.emptyMap(),Collections.singletonList(target),moves);Files.move(source.toPath(),target.toPath());assertFalse(source.exists());WorkspaceBackup.finishPending(w.app);assertArrayEquals(new byte[]{4,5,6},Files.readAllBytes(source.toPath()));assertFalse(target.exists());assertFalse(WorkspaceBackup.pending(w.app).exists());}
    @Test public void localRecoveryRetainsTheOldConversationSnapshotAfterItChanges()throws Exception{w.book("Livro.txt","Texto.");SeekyAiStore store=new SeekyAiStore(w.app);SeekyAiStore.Session session=store.create("Livro","Texto.","Parte 1","","text/plain","Livro.txt",0,0,0);session.append("Primeira pergunta",new SeekyAiCore.Result("Resposta original.",false));store.save(session);File recovery=WorkspaceBackup.recovery(w.app,()->false,s->{});session.append("Nova pergunta",new SeekyAiCore.Result("Resposta nova.",false));store.save(session);try(WorkspaceBackup.Staged staged=WorkspaceBackup.stage(w.app,recovery,true,()->false,s->{})){WorkspaceBackup.restore(w.app,staged,()->false,s->{});}SeekyAiStore.Session restored=new SeekyAiStore(w.app).load(session.id());assertEquals(2,restored.messages.size());assertEquals("Resposta original.",restored.messages.get(1).text);}
    @Test public void aCommittedRestoreJobCannotReplaceLaterUserEditsWhenResumed()throws Exception{String id=w.job("restore",new JSONObject());w.app.getSharedPreferences("reading_tools",0).edit().putString("last_restore_job",id).apply();w.book("Depois.txt","Conteúdo criado depois do restauro.");w.run(id);assertEquals(1,w.materials());try(TaskStore db=new TaskStore(w.app)){assertEquals("complete",db.job(id).s("state"));}}
}
